#!/bin/bash
# CR City Hotel rev16 FINAL: carpeta de entrega (estructura O'Reilly rev30, U-145) + subcompuertas + compuerta completa.
set -e
source /root/cr/work/scripts/env.sh
D=$W/entrega; E="$D/rev16 FINAL — ESTA ES LA VERSIÓN FINAL PARA REVISAR"
rm -rf "$D" && mkdir -p "$E/Take-off" "$E/Planos marcados" "$E/Auditoria/burbujas" "$E/Auditoria/schedules" "$E/Auditoria/review_items" "$E/Auditoria/rfi_img" "$E/Auditoria/resolucion_AB" "$E/Auditoria/barrido_tags"
ln -s $W/etapas $D/takeoff_work_etapas; ln -s $W $D/takeoff_work
# burbujas_unir.py ya corrido; burbujas_verificadas.json final (con destinos agregados a mano) es la fuente -- no re-unir
cp $W/set_texto.json $W/indep/fichas.json $W/indep/schedules_indep.json $W/proceso/proyecto_datos.json $D/
cp $W/burbujas/burbujas_verificadas.json $D/; cp -a $W/burbujas/img_verif $D/burbujas_img
cp $W/burbujas/img_verif/*.png "$E/Auditoria/burbujas/"; cp $W/burbujas/burbujas_verificadas.json $W/burbujas/CADENA.md $W/burbujas/callouts_no_aplican.json "$E/Auditoria/burbujas/"
cp $W/indep/schedules_indep.json $W/indep/fichas.json $W/indep/NOTAS.md "$E/Auditoria/schedules/"; cp $W/indep/img/*.png "$E/Auditoria/schedules/" 2>/dev/null || true
X=$W/etapas/8_excel/CR_City_Hotel_Takeoff_FINAL_rev16.xlsx
ln -s $X "$E/Take-off/CR_City_Hotel_Takeoff_FINAL_rev16.xlsx"
[ -f $X.sello.json ] && ln -s $X.sello.json "$E/Take-off/CR_City_Hotel_Takeoff_FINAL_rev16.xlsx.sello.json"
cp $W/etapas/8_excel/CR_City_Hotel_markups_rev16.pdf "$E/Planos marcados/CR_City_Hotel_markups_rev16 - OPEN THIS IN BLUEBEAM (walls + ceilings, editable).pdf"
cp $W/etapas/7_imagenes/*" - IMAGE ONLY (not editable) - "*" rev16.png" "$E/Planos marcados/"
cp $W/etapas/4_canon/img/rfi/*.png "$E/Auditoria/rfi_img/"; cp $W/etapas/4_canon/img/rfi/*.png "$E/Auditoria/review_items/"
cp $W/etapas/3_revision/resolucion*.md $W/etapas/3_revision/revision.md $W/etapas/3_revision/comparacion_AB.json "$E/Auditoria/resolucion_AB/"
cp $W/etapas/COBERTURA_PASO12.md $W/etapas/COBERTURA_PASO12.json "$E/Auditoria/"; cp $W/etapas/VERIFICACION_MARKUPS.md $W/etapas/TOOL_LIMITS_CALC.md $W/etapas/PROCESO_CORRIDA.md $W/etapas/6_markups/rcp_polys_check.json "$E/Auditoria/"
cp $W/etapas/1_inventario/inventario.md $W/etapas/1_inventario/inventario.json "$E/Auditoria/barrido_tags/"; cp -a $W/etapas/1_inventario/recortes "$E/Auditoria/barrido_tags/"; mkdir -p "$E/Auditoria/evidencia_walls"; cp -a $W/etapas/7_imagenes/walls $W/etapas/7_imagenes/alturas "$E/Auditoria/evidencia_walls/"
cp $W/comparacion_sets.json "$E/Auditoria/comparacion_sets_2025_vs_2026.json"
[ -d $W/auditoria_U138 ] && mkdir -p "$E/Auditoria/auditoria_U138" && cp -a $W/auditoria_U138/. "$E/Auditoria/auditoria_U138/"
[ -d $W/auditoria_U138_2 ] && mkdir -p "$E/Auditoria/auditoria_U138_2" && cp -a $W/auditoria_U138_2/INFORME_AUDITORIA_U138_2.md $W/auditoria_U138_2/RESOLUCION_HALLAZGOS_U138_2.md $W/auditoria_U138_2/BRIEF.md $W/auditoria_U138_2/img "$E/Auditoria/auditoria_U138_2/"
[ -d $W/Proposal ] && mkdir -p "$E/Proposal" && cp -a $W/Proposal/. "$E/Proposal/"
python3 -I $W/scripts/tiempos.py > /dev/null; cp $W/entrega.json $W/TIEMPOS.md $D/
python3 -I $W/scripts/delta_rev.py rev1 rev2 > /dev/null; python3 -I $W/scripts/delta_rev.py rev2 rev3 > /dev/null; python3 -I $W/scripts/delta_rev.py rev3 rev4 > /dev/null; python3 -I $W/scripts/delta_rev.py rev4 rev5 > /dev/null; python3 -I $W/scripts/delta_rev.py rev5 rev6 > /dev/null; python3 -I $W/scripts/delta_rev.py rev6 rev7 > /dev/null; python3 -I $W/scripts/delta_rev.py rev7 rev8 > /dev/null; python3 -I $W/scripts/delta_rev.py rev8 rev9 > /dev/null; python3 -I $W/scripts/delta_rev.py rev9 rev10 > /dev/null; python3 -I $W/scripts/delta_rev.py rev10 rev11 > /dev/null; python3 -I $W/scripts/delta_rev.py rev11 rev12 > /dev/null; python3 -I $W/scripts/delta_rev.py rev12 rev13 > /dev/null; python3 -I $W/scripts/delta_rev.py rev13 rev14 > /dev/null; python3 -I $W/scripts/delta_rev.py rev14 rev15 > /dev/null; python3 -I $W/scripts/delta_rev.py rev15 rev16 > /dev/null; cp $W/etapas/DELTA_rev4_rev5.md $W/etapas/DELTA_rev5_rev6.md $W/etapas/DELTA_rev6_rev7.md $W/etapas/DELTA_rev7_rev8.md $W/etapas/DELTA_rev8_rev9.md $W/etapas/DELTA_rev9_rev10.md $W/etapas/DELTA_rev10_rev11.md $W/etapas/DELTA_rev11_rev12.md $W/etapas/DELTA_rev12_rev13.md $W/etapas/DELTA_rev13_rev14.md $W/etapas/DELTA_rev14_rev15.md $W/etapas/DELTA_rev15_rev16.md "$E/Auditoria/"; cp $W/BITACORA_rev16.md "$E/BITACORA.md"; cp $W/RESUMEN_rev5.md $W/RESUMEN_rev6.md $W/RESUMEN_rev7.md $W/RESUMEN_rev8.md $W/RESUMEN_rev9.md $W/RESUMEN_rev10.md $W/RESUMEN_rev11.md $W/RESUMEN_rev12.md $W/RESUMEN_rev13.md $W/RESUMEN_rev14.md $W/RESUMEN_rev15.md $W/RESUMEN_rev16.md "$E/"; mkdir -p "$E/Auditoria/contornos_rev9"; cp $W/etapas/4_canon/img/rev9/*.png $W/etapas/4_canon/rev9/contornos_*.json $W/etapas/4_canon/rev9/ajustes.json "$E/Auditoria/contornos_rev9/" 2>/dev/null; mkdir -p "$E/Auditoria/auditoria_rev13_rev14" "$E/Auditoria/revision_completa_rev15" "$E/Auditoria/revision_dirigida_rev16"; cp $W/etapas/4_canon/img/rev13/*.png $W/etapas/4_canon/img/rev14/*.png "$E/Auditoria/auditoria_rev13_rev14/" 2>/dev/null; cp $W/etapas/4_canon/img/rev15/*.png $W/etapas/4_canon/rev15/*.json "$E/Auditoria/revision_completa_rev15/" 2>/dev/null; cp $W/etapas/4_canon/img/rev16/*.png $W/etapas/4_canon/rev16/*.json "$E/Auditoria/revision_dirigida_rev16/" 2>/dev/null; mkdir -p "$E/Auditoria/auditoria_rev8"; cp $W/etapas/4_canon/img/rev8/*.png $W/etapas/4_canon/out/rev8_walls.json $W/etapas/4_canon/out/vanos_puertas.json "$E/Auditoria/auditoria_rev8/" 2>/dev/null; mkdir -p "$E/Auditoria/rcp_rev7"; cp $W/etapas/6_markups/rcp_misc_log.json $W/etapas/6_markups/rcp_png/*.png "$E/Auditoria/rcp_rev7/" 2>/dev/null; mkdir -p "$E/Auditoria/auditoria_rev6"; cp $W/etapas/4_canon/img/rev6/*.png $W/etapas/4_canon/out/perimetros_angle.json $W/etapas/4_canon/out/banos_cbu.json "$E/Auditoria/auditoria_rev6/" 2>/dev/null; mkdir -p "$E/Auditoria/code_review_rev5"; cp $W/etapas/4_canon/img/rev5/*.png $W/etapas/4_canon/rev5/*.json "$E/Auditoria/code_review_rev5/" 2>/dev/null; cp $W/etapas/DELTA_rev1_rev2.md $W/etapas/DELTA_rev2_rev3.md $W/etapas/DELTA_rev3_rev4.md "$E/Auditoria/"; mkdir -p "$E/Auditoria/rcp_rev4"; cp $W/etapas/4_canon/img/rcp_rev4/*.png "$E/Auditoria/rcp_rev4/"
python3 -I $W/scripts/hacer_docs.py "$E" $W/proceso/proyecto_datos.json $W/takeoff.json $W/etapas/4_canon/takeoff_canon.json
(cd $D && python3 $T/compuerta_entrega.py detalles . | tail -1)
(cd $D && python3 $T/compuerta_entrega.py schedules . | tail -1)
(cd $D && python3 $T/compuerta_entrega.py banco . --cache /home/user/reading-plans > banco.txt 2>&1 || true; tail -3 banco.txt)
(cd $D && timeout 2400 python3 $T/compuerta_entrega.py . > gate.txt 2>&1 || true)
grep -E "^(FAIL|AMBER)|COMPUERTA" $D/gate.txt | head -60
